package ro.leo.visual;
import android.app.*;import android.content.*;import android.telecom.*;
/** Owned call notification IDs only. System Ringer keeps ringing ownership. */
final class CallNotices {
 static final int LIVE=63001,MISSED=63002;
 static NotificationManager manager(Context c){return (NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);}
 static void ongoing(Context c,Call call){NotificationManager nm=manager(c);NotificationChannel channel=new NotificationChannel("leo-call-quiet","Apel în curs Leo",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);channel.enableVibration(false);nm.createNotificationChannel(channel);PendingIntent open=PendingIntent.getActivity(c,LIVE,new Intent(c,InCallActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,"leo-call-quiet").setSmallIcon(android.R.drawable.sym_action_call).setContentTitle(CallPresentation.state(call.getState())).setContentText(LeoInCallService.identity(call)).setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_CALL);nm.notify("leo-call",LIVE,b.build());}
 static void cancelOngoing(Context c){manager(c).cancel("leo-call",LIVE);}
 static void missed(Context c,int count){NotificationManager nm=manager(c);if(count<=0){nm.cancel("leo-call",MISSED);return;}nm.createNotificationChannel(new NotificationChannel("leo-missed","Apeluri pierdute Leo",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,MISSED,new Intent(c,PhoneActivity.class).putExtra("history",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify("leo-call",MISSED,new Notification.Builder(c,"leo-missed").setSmallIcon(android.R.drawable.sym_call_missed).setContentTitle(count==1?"Apel pierdut":count+" apeluri pierdute").setContentText("Deschide istoricul în Leo").setContentIntent(open).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build());}
 static void clearMissed(Context c){try{((TelecomManager)c.getSystemService(Context.TELECOM_SERVICE)).cancelMissedCallsNotification();}catch(RuntimeException ignored){}manager(c).cancel("leo-call",MISSED);}
}
